"""Restore only a retained, verified private generation, never a default identity."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import secrets


def manifest(directory):
    return {name: hashlib.sha256((directory / name).read_bytes()).hexdigest()
            for name in ('server.pem', 'server.key', 'trust.pem')}


def activate(state, generation):
    state = Path(state).resolve()
    if generation not in ('baseline', 'overlap', 'candidate'):
        raise ValueError('unknown generation')
    target = state / 'versions' / generation
    if target.is_symlink() or not target.is_dir():
        raise ValueError('missing retained generation')
    if manifest(target) != json.loads((target / 'sha256.json').read_text()):
        raise ValueError('retained generation changed')
    temporary = state / ('.active-' + secrets.token_hex(8))
    try:
        temporary.symlink_to('versions/' + generation, target_is_directory=True)
        os.replace(temporary, state / 'active')
    finally:
        temporary.unlink(missing_ok=True)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--state', required=True)
    parser.add_argument('--generation', choices=('baseline', 'overlap'), required=True)
    args = parser.parse_args()
    activate(args.state, args.generation)
    try:
        print(json.dumps({'restored': args.generation}), flush=True)
    except OSError as error:
        import sys
        sys.stdout = open(os.devnull, 'w')
        raise ValueError('state committed; output failed: ' + str(error)) from error


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, KeyError) as error:
        import sys
        print(str(error), file=sys.stderr); sys.exit(2)

