import json
import os
from pathlib import Path
import sqlite3
import tempfile
import zlib

APP_ID = 1330664262


def connect(path, readonly=False, must_exist=False):
    path = Path(path).resolve()
    if readonly:
        conn = sqlite3.connect(path.as_uri() + '?mode=ro', uri=True, timeout=.2)
    elif must_exist:
        conn = sqlite3.connect(path.as_uri() + '?mode=rw', uri=True, timeout=.2)
    else:
        conn = sqlite3.connect(path, timeout=.2)
    conn.execute('PRAGMA foreign_keys=ON')
    if readonly:
        conn.execute('PRAGMA query_only=ON')
        def authorize(action, first, second, database, source):
            if action in (sqlite3.SQLITE_SELECT, sqlite3.SQLITE_READ):
                return sqlite3.SQLITE_OK
            if action == sqlite3.SQLITE_FUNCTION and (second or first or '').lower() not in ('load_extension', 'readfile', 'writefile'):
                return sqlite3.SQLITE_OK
            if action == sqlite3.SQLITE_PRAGMA and first.lower() in ('application_id', 'user_version', 'integrity_check', 'foreign_key_check') and second is None:
                return sqlite3.SQLITE_OK
            return sqlite3.SQLITE_DENY
        conn.set_authorizer(authorize)
    conn.row_factory = sqlite3.Row
    return conn


def verify(conn):
    if conn.execute('PRAGMA application_id').fetchone()[0] != APP_ID or conn.execute('PRAGMA user_version').fetchone()[0] != 1:
        raise ValueError('not an OpsForge evidence database')
    if conn.execute('PRAGMA integrity_check').fetchone()[0] != 'ok' or conn.execute('PRAGMA foreign_key_check').fetchall():
        raise ValueError('database integrity failed')


def publish(path, raw):
    path = Path(path)
    if path.exists() or path.is_symlink():
        raise ValueError('output exists')
    descriptor, temporary = tempfile.mkstemp(prefix='.evidence-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'wb') as target:
            target.write(raw); target.flush(); os.fsync(target.fileno())
        os.link(temporary, path)
    finally:
        Path(temporary).unlink(missing_ok=True)


def main_error(fn):
    try:
        fn()
    except (OSError, ValueError, KeyError, TypeError, EOFError, zlib.error, sqlite3.Error) as error:
        import sys
        print(str(error), file=sys.stderr); sys.exit(2)

