import argparse
import datetime
import gzip
import hashlib
import io
import json
import os
from pathlib import Path
import re
import sqlite3

from evidence_common import connect, verify, main_error


def text(value):
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9_.-]{1,128}', value):
        raise ValueError('invalid identifier')
    return value


def integer(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise ValueError('invalid integer')
    return value


def unique(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise ValueError('duplicate JSON key')
        value[key] = item
    return value


def loads(raw):
    def reject(value):
        raise ValueError('nonfinite JSON')
    return json.loads(raw, object_pairs_hook=unique, parse_constant=reject)


def parse(manifest_path, input_root):
    manifest_raw = Path(manifest_path).read_bytes()
    manifest = loads(manifest_raw.decode('utf8'))
    if not isinstance(manifest, dict) or set(manifest) != {'batch_id', 'captures'} or not isinstance(manifest['captures'], list):
        raise ValueError('manifest schema')
    text(manifest['batch_id']); root = Path(input_root).resolve(); captures = []; seen = set()
    for capture in manifest['captures']:
        if not isinstance(capture, dict) or set(capture) != {'capture_id', 'file', 'sha256', 'proxy_id', 'boot_id', 'revision', 'line_count'}:
            raise ValueError('capture schema')
        for key in ('capture_id', 'proxy_id', 'boot_id', 'revision'):
            text(capture[key])
        if capture['capture_id'] in seen:
            raise ValueError('duplicate capture id')
        seen.add(capture['capture_id']); integer(capture['line_count'], 0, 50000)
        if not isinstance(capture['file'], str) or not capture['file'] or Path(capture['file']).is_absolute() or '..' in Path(capture['file']).parts:
            raise ValueError('unsafe capture path')
        if not capture['file'].endswith(('.jsonl', '.jsonl.gz')):
            raise ValueError('unsupported capture encoding')
        path = (root/capture['file']).resolve()
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError('capture escaped input root')
        if not isinstance(capture['sha256'], str) or not re.fullmatch('[0-9a-f]{64}', capture['sha256']):
            raise ValueError('capture digest')
        raw = path.read_bytes()
        if len(raw) > 4*1024*1024 or hashlib.sha256(raw).hexdigest() != capture['sha256']:
            raise ValueError('capture bytes mismatch')
        if capture['file'].endswith('.jsonl.gz'):
            with gzip.GzipFile(fileobj=io.BytesIO(raw)) as compressed:
                raw = compressed.read(8*1024*1024+1)
        if len(raw) > 8*1024*1024:
            raise ValueError('capture too large')
        lines = raw.decode('utf8').split('\n')
        if lines and lines[-1] == '':
            lines.pop()
        if len(lines) != capture['line_count']:
            raise ValueError('capture line count mismatch')
        events = []
        for line in lines:
            if line.endswith('\r'):
                line = line[:-1]
            if not line:
                raise ValueError('blank physical JSONL line')
            event = loads(line)
            if not isinstance(event, dict) or set(event) != {'stream_id', 'request_id', 'start_time', 'response_code', 'response_flags', 'response_code_details', 'upstream_request_attempt_count'}:
                raise ValueError('final log record schema')
            text(event['stream_id']); text(event['request_id']); integer(event['response_code'], 100, 599)
            if not isinstance(event['response_flags'], list) or any(not isinstance(flag, str) or not re.fullmatch('[A-Z][A-Z0-9_]{0,31}', flag) for flag in event['response_flags']):
                raise ValueError('response flags')
            if len(event['response_flags']) != len(set(event['response_flags'])):
                raise ValueError('duplicate flag')
            if not isinstance(event['response_code_details'], str) or not event['response_code_details'] or len(event['response_code_details']) > 1000:
                raise ValueError('response detail')
            if event['upstream_request_attempt_count'] is not None:
                integer(event['upstream_request_attempt_count'], 0, 1000000)
            timestamp = event['start_time']
            if not isinstance(timestamp, str) or not re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,6})?Z', timestamp):
                raise ValueError('UTC timestamp required')
            moment = datetime.datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
            delta = moment-datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            micros = (delta.days*86400+delta.seconds)*1000000+delta.microseconds
            if not 0 <= micros <= 2**63-1:
                raise ValueError('timestamp outside SQLite range')
            event['response_flags'] = sorted(event['response_flags'])
            canonical = json.dumps(event, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
            events.append((event, canonical, micros))
        captures.append((capture, events))
    return manifest, hashlib.sha256(manifest_raw).hexdigest(), captures


def run(args):
    manifest, manifest_sha, captures = parse(args.manifest, args.input_root)
    if args.crash_after is not None:
        integer(args.crash_after, 1, 50000000)
    path = Path(args.db)
    existed = path.exists()
    conn = connect(path)
    try:
        if not existed:
            conn.executescript(Path(__file__).with_name('schema.sql').read_text())
        verify(conn)
        conn.execute('PRAGMA synchronous=FULL'); conn.execute('PRAGMA cache_size=2')
        conn.execute('BEGIN IMMEDIATE')
        old = conn.execute('SELECT manifest_sha256 FROM batches WHERE batch_id=?', (manifest['batch_id'],)).fetchone()
        if old is not None:
            if old[0] != manifest_sha:
                raise ValueError('batch id reused with different manifest')
            conn.rollback()
            print(json.dumps({'batch_id': manifest['batch_id'], 'replayed': True})); return
        processed = 0
        for capture, events in captures:
            values = tuple(capture[key] for key in ('capture_id', 'file', 'sha256', 'proxy_id', 'boot_id', 'revision', 'line_count'))
            existing = conn.execute('SELECT capture_id,file,sha256,proxy_id,boot_id,revision,line_count FROM captures WHERE capture_id=?', (capture['capture_id'],)).fetchone()
            if existing is not None and tuple(existing) != values:
                raise ValueError('capture identity conflict')
            conn.execute('INSERT OR IGNORE INTO captures VALUES(?,?,?,?,?,?,?)', values)
            for line_no, (event, canonical, micros) in enumerate(events, 1):
                identity = (capture['proxy_id'], capture['boot_id'], event['stream_id'])
                old = conn.execute('SELECT canonical,revision FROM events WHERE proxy_id=? AND boot_id=? AND stream_id=?', identity).fetchone()
                if old is not None and (old['canonical'] != canonical or old['revision'] != capture['revision']):
                    raise ValueError('same proxy incarnation/stream has conflicting final evidence')
                conn.execute('INSERT OR IGNORE INTO events VALUES(?,?,?,?,?,?,?,?,?,?,?)',
                             identity + (event['request_id'], capture['revision'], micros, event['response_code'], ','.join(event['response_flags']),
                                         event['response_code_details'], event['upstream_request_attempt_count'], canonical))
                conn.execute('INSERT OR IGNORE INTO locations VALUES(?,?,?,?,?)', (capture['capture_id'], line_no) + identity)
                processed += 1
                if args.crash_after is not None and processed == args.crash_after:
                    os._exit(73)
        conn.execute('INSERT INTO batches VALUES(?,?)', (manifest['batch_id'], manifest_sha))
        conn.commit()
        print(json.dumps({'batch_id': manifest['batch_id'], 'replayed': False}))
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True); parser.add_argument('--manifest', required=True)
    parser.add_argument('--input-root', required=True); parser.add_argument('--crash-after', type=int)
    run(parser.parse_args())


if __name__ == '__main__':
    main_error(main)

