import argparse
import json
from pathlib import Path

from evidence_common import connect, verify, publish, main_error


def classify(event):
    if event['response_code'] != 429:
        return 'other'
    flags = event['response_flags']
    if 'RL' in flags and event['response_code_details'] == 'rate_limited':
        return 'proxy_rate_limited'
    if 'RL' not in flags and event['response_code_details'] == 'via_upstream':
        return 'upstream_429'
    return 'unknown_429'


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True); parser.add_argument('--output', required=True)
    args = parser.parse_args()
    with connect(args.db, readonly=True) as conn:
        verify(conn)
        counts = {table: conn.execute('SELECT COUNT(*) FROM '+table).fetchone()[0] for table in ('events', 'captures', 'batches')}
        events = {}
        for row in conn.execute(Path(__file__).with_name('queries.sql').read_text()):
            key = (row['proxy_id'], row['boot_id'], row['stream_id'])
            if key not in events:
                event = {name: row[name] for name in ('proxy_id', 'boot_id', 'stream_id', 'request_id', 'revision', 'observed_us', 'response_code', 'response_code_details', 'attempts')}
                event['response_flags'] = row['response_flags'].split(',') if row['response_flags'] else []
                event['classification'] = classify(event); event['provenance'] = []
                events[key] = event
            events[key]['provenance'].append({'capture_id': row['capture_id'], 'line_no': row['line_no'], 'source_sha256': row['source_sha256']})
        groups = {}
        for event in events.values():
            request = groups.setdefault(event['request_id'], {'request_id': event['request_id'], 'observations': [],
                'classifications': {key: 0 for key in ('proxy_rate_limited', 'upstream_429', 'unknown_429', 'other')}, 'revisions': []})
            request['observations'].append(event); request['classifications'][event['classification']] += 1
            if event['revision'] not in request['revisions']:
                request['revisions'].append(event['revision'])
        for request in groups.values():
            request['revisions'].sort()
            request['observations'].sort(key=lambda event: (event['observed_us'], event['proxy_id'], event['boot_id'], event['stream_id']))
        report = {'event_count': counts['events'], 'capture_count': counts['captures'], 'batch_count': counts['batches'],
                  'requests': [groups[key] for key in sorted(groups)],
                  'scope': 'offline supplied final logs; no fresh traffic, unique business request, or mesh health proof'}
    publish(args.output, json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2).encode('utf8'))
    print(json.dumps({'event_count': report['event_count'], 'request_groups': len(groups)}))


if __name__ == '__main__':
    main_error(main)
